export const appearanceColors={bg:'Page background',paper:'Card and sidebar background',ink:'Main text',muted:'Secondary text',line:'Borders',green:'Primary colour',soft:'Soft background',gold:'Accent colour',hero:'Hero background',heroText:'Hero text',buttonText:'Primary button text'};
export const appearanceDefaults={bg:'#f7f8f5',paper:'#ffffff',ink:'#203a33',muted:'#7a8580',line:'#e7eae5',green:'#244f40',soft:'#edf3ed',gold:'#b79555',hero:'#e8eee5',heroText:'#203a33',buttonText:'#ffffff',darkBg:'#14241f',darkPaper:'#1b2d26',darkInk:'#e1e9df',darkMuted:'#9ea9a0',darkLine:'#314338',darkGreen:'#749d81',darkSoft:'#293f31',darkGold:'#b79555',darkHero:'#203e31',darkHeroText:'#e1e9df',darkButtonText:'#10271b',font:'modern',headings:'classic',radius:12,buttonRadius:6,fontSize:14,spacing:22,contentWidth:1600,sidebarWidth:248,shadow:'none',customCSS:''};
const fonts={modern:"'DM Sans',Arial,sans-serif",system:'system-ui,Arial,sans-serif',classic:'Georgia,serif',mono:'ui-monospace,monospace'};
export function normalizeAppearance(raw={},strict=false){const out={...appearanceDefaults};for(const key of Object.keys(out)){if(raw[key]===undefined)continue;const value=raw[key];if(/^#/.test(String(out[key]))){if(!/^#[0-9a-f]{6}$/i.test(value)){if(strict)throw new Error('Choose a valid six-digit colour.');continue;}out[key]=value;}else if(['font','headings'].includes(key)){if(!fonts[value]){if(strict)throw new Error('Choose a supported font.');continue;}out[key]=value;}else if(key==='shadow'){if(!['none','soft','raised'].includes(value)){if(strict)throw new Error('Choose a supported shadow.');continue;}out[key]=value;}else if(key==='customCSS'){if(typeof value!=='string'||value.length>16000||/@import|url\s*\(|expression\s*\(|javascript:|[<>]/i.test(value)){if(strict)throw new Error('Custom CSS must be under 16,000 characters and cannot load URLs, imports or scripts.');continue;}out[key]=value;}else{const ranges={radius:[0,40],buttonRadius:[0,40],fontSize:[12,20],spacing:[8,40],contentWidth:[800,2200],sidebarWidth:[200,340]};const [min,max]=ranges[key]||[0,100];if(!Number.isFinite(Number(value))||Number(value)<min||Number(value)>max){if(strict)throw new Error('Appearance values are outside their allowed range.');continue;}out[key]=Number(value);}}return out;}
export function appearanceCSS(value){const a=normalizeAppearance(value),variables=Object.keys(appearanceColors).filter(key=>!['hero','heroText','buttonText'].includes(key));const vars=dark=>variables.map(key=>`--${key}:${a[dark?'dark'+key[0].toUpperCase()+key.slice(1):key]}`).join(';');return `:root{${vars(false)};--sans:${fonts[a.font]};--serif:${fonts[a.headings]}}body.dark{${vars(true)}}body{font-size:${a.fontSize}px}.card,.resource,.workspace{border-radius:${a.radius}px}.card{box-shadow:${{none:'none',soft:'0 4px 18px #0000000b',raised:'0 10px 35px #0000001a'}[a.shadow]}}.btn,.quick{border-radius:${a.buttonRadius}px}.grid,.dashboard-grid,.two-col{gap:${a.spacing}px}main{max-width:${a.contentWidth}px;margin-inline:auto}.hero{background:${a.hero};color:${a.heroText}}.hero h2,.hero p{color:inherit}body.dark .hero{background:${a.darkHero};color:${a.darkHeroText}}.btn.primary{background:var(--green);color:${a.buttonText}}body.dark .btn.primary{color:${a.darkButtonText}}@media(min-width:901px){#sidebar{width:${a.sidebarWidth}px}#shell{margin-left:${a.sidebarWidth}px}body.sidebar-collapsed #shell{margin-left:0}}${a.customCSS}`;}
export function applyAppearance(value){if(typeof document==='undefined'||!document.head)return;if(new URLSearchParams(location.search||'').get('safeAppearance')==='1')return;let style=document.querySelector('#site-appearance');if(!style){style=document.createElement('style');style.id='site-appearance';document.head.append(style);}style.textContent=appearanceCSS(value);}
